function load(text,name,isDemo=false){try{parsed=Health.parseCSV(text);mapping=Health.autoMap(parsed.headers);demo=isDemo;$('source').textContent=(demo?'FICTIONAL DEMO / ':'LOCAL FILE / ')+name;$('mapping').innerHTML=Object.keys(Health.fields).map(k=>'<label>'+Health.labels[k]+'<select data-field="'+k+'"><option value="">Not available</option>'+parsed.headers.map(h=>'<option '+(mapping[k]===h?'selected':'')+'>'+esc(h)+'</option>').join('')+'</select></label>').join('');$('mapping').querySelectorAll('select').forEach(el=>el.onchange=()=>{mapping[el.dataset.field]=el.value;invalidate();});$('run').disabled=false;$('setup').open=!isDemo;if(isDemo)$('asof').value='2026-10-30';else $('asof').value=new Date().toISOString().slice(0,10);run();}catch(e){error(e.message);}}
function invalidate(){result=null;['export','copy','download-brief'].forEach(id=>$(id).disabled=true);['total','affected','high','coverage'].forEach(id=>$(id).textContent='—');$('coverage-note').textContent='Settings changed — run health check';$('findings').innerHTML='<div class="empty">Settings changed. Run health check to refresh results.</div>';$('check-list').innerHTML='';$('brief').value='';$('count').textContent='0';$('shown').textContent='';}
function run(){if(!parsed)return;try{if(!mapping.id||!mapping.job||!mapping.status)throw Error('Map Application ID, Job title and Application status before running.');let mapped=Object.values(mapping).filter(Boolean);if(new Set(mapped).size!==mapped.length)throw Error('Each export column can only be mapped once.');if(!Health.date($('asof').value))throw Error('Choose a valid audit date.');for(let id of ['stale','jobdays'])if(!Number.isInteger(Number($(id).value))||Number($(id).value)<1||Number($(id).value)>365)throw Error('Thresholds must be whole numbers between 1 and 365.');result=Health.audit(parsed,mapping,{asOf:$('asof').value,staleDays:$('stale').value,jobDays:$('jobdays').value});error('');$('total').textContent=result.records.length;$('affected').textContent=new Set(result.issues.filter(x=>x.scope==='application').map(x=>x.row)).size;$('high').textContent=result.issues.filter(x=>x.severity==='High').length;let n=result.checks.filter(x=>x.supported).length;$('coverage').textContent=n+' / '+result.checks.length;$('coverage-note').textContent=(result.checks.length-n)+' checks unavailable';$('count').textContent=result.issues.length;$('rule').innerHTML='<option value="">All issue types</option>'+[...new Set(result.issues.map(x=>x.rule))].map(s=>'<option>'+esc(s)+'</option>').join('');$('check-list').innerHTML=result.checks.map(c=>'<article class="check"><span class="badge">'+(c.supported?c.count+' findings':'Unavailable')+'</span><b>'+esc(c.name)+'</b><p>Requires: '+esc(c.needs)+'</p>'+(c.supported?'':'<p>Map the required columns to enable this check.</p>')+'</article>').join('');$('brief').value=Health.brief(result);['export','copy','download-brief'].forEach(id=>$(id).disabled=false);render();}catch(e){invalidate();error(e.message);}}
function render(){if(!result)return;let q=$('search').value.toLowerCase(),s=$('severity').value,t=$('rule').value;let items=result.issues.filter(i=>(!s||i.severity===s)&&(!t||i.rule===t)&&[i.candidate,i.job,i.rule,i.id].join(' ').toLowerCase().includes(q));$('shown').textContent=items.length+' of '+result.issues.length;$('findings').innerHTML=items.length?items.slice(0,500).map(i=>'<article class="finding"><span class="badge '+i.severity+'">'+i.severity+'</span><div><h4>'+esc(i.rule)+'</h4><p>'+esc(i.scope==='role'?i.job:i.candidate)+'</p><small>'+esc(i.id)+' · CSV row '+i.row+'</small></div><div><h4>'+esc(i.job)+'</h4><p>'+esc(i.evidence)+'</p></div><div><h4>Suggested action</h4><p>'+esc(i.action)+'</p></div></article>').join('')+(items.length>500?'<p class="muted">Showing the first 500 findings. Export the queue for all findings.</p>':''):'<div class="empty"><h3>'+(result.issues.length?'No matching findings.':'No findings in the available checks.')+'</h3><p>'+(result.issues.length?'Try changing the filters.':'Check coverage and export completeness before drawing conclusions.')+'</p></div>';}
